        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack.pop() != "(":
                    return False
        return not stack

    # Step 4: Add each separated group to a list
    separated_groups = [group for group in groups if is_balanced(group)]

    # Step 5: Return the list of separated groups
